sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here
   try {
        // -------------------------------
        // 1️⃣ Check if request body exists AND has keys
        // -------------------------------
        var body = request.body && request.body.data;

        if (!body || Object.keys(body).length === 0) {
            response.setStatus(400);
            response.setBody({
                error: "Request body is required anitha"
            });
            return;
        }
        // -------------------------------
        // 2️⃣ Now validate required fields
        // -------------------------------
        if (!body.emp_number) {
            response.setStatus(400);
            response.setBody({
                error: "Missing required parameter: Emp Number"
            });
            return;
        }
        // -------------------------------
        // 3️⃣ Proceed to get  employee details (example)
        // -------------------------------
        var result = [];
        var empGR = new GlideRecord('u_employee');
        empGR.addQuery('u_empnumber', body.emp_number);
        empGR.query();

        while (empGR.next()) {
            result.push({
                emp_number: empGR.u_empnumber.toString(),
                first_name: empGR.u_firstname.toString(),
                last_name: empGR.u_lastname.toString(),
                age: empGR.u_age.toString(),
                created_by: empGR.u_createdby.toString(),
                salary: empGR.u_salary.toString()
            });
        }
        response.setStatus(200);
        response.setBody(result);

	} catch (ex) {
        response.setStatus(500);
        response.setBody({
            error: "Internal Server Error",
            message: ex.message
        });
    }
})(request, response);
